typedef float rational_t;

template <class T> class my_allocator {};

template <class T, class Alloc = my_allocator<T> >
class vector
{
public:
  typedef const T* const_iterator;
  T* start;
  T* finish;
  T* end_of_storage;
  const_iterator begin() const { return start; }
};

class vector3d
{
public:
  rational_t x, y, z;
  rational_t length2() const { return x*x + y*y + z*z; }
};

inline vector3d operator-(const vector3d& a, const vector3d& b)
{
  vector3d result = { a.x-b.x, a.y-b.y, a.z-b.z };
  return result;
}

typedef vector<vector3d, my_allocator<vector3d> > vectorvector;

class entity;
class po;

class collision_geometry
{
public:
  virtual ~collision_geometry();
  virtual collision_geometry* make_instance(entity*) const = 0;
  virtual void xform(const po&);
  virtual void apply_radius_scale(rational_t);
  virtual void split_xform(const po&, const po&, int);
  virtual void split_xform(const po&, const po&, const po&, int, int);
  virtual rational_t get_radius() const;
  virtual rational_t get_core_radius() const;
  virtual const vector3d& get_abs_position() const;
  virtual void estimate_physical_properties(entity*, rational_t) = 0;
  virtual void get_closest_point_along_dir(vector3d*, const vector3d&) const = 0;
  virtual void get_min_extent(vector3d*) const;
  virtual void get_max_extent(vector3d*) const;
  virtual const vector3d& get_pivot() const;
  virtual unsigned int get_type() const = 0;
  virtual bool is_pivot_valid() const;
  virtual bool is_entity_collision() const;
  virtual bool is_camera_collision() const;
protected:
  entity* owner;
  bool valid;
};

class capsule
{
public:
  vector3d base;
  vector3d end;
  rational_t radius;
};

class collision_capsule : public collision_geometry
{
public:
  virtual ~collision_capsule();
  virtual collision_geometry* make_instance(entity*) const;
  virtual unsigned int get_type() const;
  virtual void xform(const po&);
  virtual void split_xform(const po&, const po&, int);
  virtual void apply_radius_scale(rational_t);
  virtual void estimate_physical_properties(entity*, rational_t);
  virtual void get_closest_point_along_dir(vector3d*, const vector3d&) const;
  virtual void get_min_extent(vector3d*) const;
  virtual void get_max_extent(vector3d*) const;
  virtual rational_t get_radius() const;
  virtual rational_t get_core_radius() const;
private:
  capsule rel_cap;
  capsule abs_cap;
  vector3d lag_point;
};

class cface
{
public:
  const vector3d& get_center() const { return center; }
  rational_t get_radius() const { return radius; }
private:
  unsigned short vert_refs[3];
  unsigned short my_material;
  vector3d raw_normal;
  vector3d normal __attribute__((aligned(16)));
  vector3d raw_center;
  vector3d center;
  rational_t radius;
  unsigned short flags;
};

class cg_mesh : public collision_geometry
{
public:
  int get_low_index(rational_t) const;
  int get_high_index(rational_t) const;
  const vector<cface, my_allocator<cface> >& get_cfaces() const { return cfaces; }
private:
  vector<char> raw_verts;
  vector<char> verts;
  vector<cface, my_allocator<cface> > cfaces;
};

bool collide_capsule_polygon(const collision_capsule&, const cface*,
                             const cg_mesh*, vectorvector*, vectorvector*,
                             vectorvector*, const vector3d&);

bool collide_capsule_mesh( const collision_capsule* c1, const cg_mesh* m2,
                            vectorvector* hit_list,
                            vectorvector* normal_list1,
                            vectorvector* normal_list2,
                            unsigned int ct,
                            const vector3d& rel_vel )
{
  //profiler::inst()->add_counter( profiler::PCT_GENERIC4, 1 );

  bool hit = false;
  vector3d c1pos = c1->get_abs_position();
  rational_t c1rad = c1->get_radius();
  int low = m2->get_low_index( c1pos.x - c1rad );
  if ( low >= 0 )
  {
    int high = m2->get_high_index( c1pos.x + c1rad );
    if ( low <= high )
    {
      vector<cface>::const_iterator cfi = m2->get_cfaces().begin() + low;
      vector<cface>::const_iterator cfi_end = m2->get_cfaces().begin() + high;
      for ( ; cfi<=cfi_end; ++cfi )
      {
        const cface& f2 = *cfi;
        rational_t r = f2.get_radius() + c1rad;
        if ( (c1pos-f2.get_center()).length2() < r*r )
        {
//          vector3d hit_loc;
          if ( collide_capsule_polygon( *c1, &f2, m2, hit_list, normal_list1, normal_list2, rel_vel ) )
            hit = true;
        }
      }
    }
  }
  return hit;
}
